import{_ as s,a0 as l,w as i,s as p,I as r,x as o,a1 as a,A as e,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"书评：《Ours to Hack and to Own》 | LCTT x X-CMD","titleTemplate":false,"description":"书评：《Ours to Hack and to Own》 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"书评：《Ours to Hack and to Own》 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"书评：《Ours to Hack and to Own》 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170131 Book review Ours to Hack and to Own","title":"书评：《Ours to Hack and to Own》","tag":"201801","desc":""},"relativePath":"201801/20170131 Book review Ours to Hack and to Own.md","filePath":"[post].md"}'),d={name:"201801/20170131 Book review Ours to Hack and to Own.md"};function k(w,t,m,O,f,b){const n=l("Link");return i(),p("div",null,[t[22]||(t[22]=r("h1",{id:"书评-《ours-to-hack-and-to-own》",tabindex:"-1"},[o("书评：《Ours to Hack and to Own》 "),r("a",{class:"header-anchor",href:"#书评-《ours-to-hack-and-to-own》","aria-label":"Permalink to “书评：《Ours to Hack and to Own》”"},"​")],-1)),t[23]||(t[23]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDUCATION_colorbooks.png?itok=vNhsYYyC",alt:"书评: Ours to Hack and to Own",title:"Book review: Ours to Hack and to Own"})],-1)),t[24]||(t[24]=r("p",null,"Image by : opensource.com",-1)),t[25]||(t[25]=r("p",null,"私有制的时代看起来似乎结束了，在这里我将不仅仅讨论那些由我们中的许多人引入到我们的家庭与生活的设备和软件，我也将讨论这些设备与应用依赖的平台与服务。",-1)),r("p",null,[t[1]||(t[1]=o("尽管我们使用的许多服务是免费的，但我们对它们并没有任何控制权。本质上讲，这些企业确实控制着我们所看到的、听到的以及阅读到的内容。不仅如此，许多企业还在改变工作的本质。他们正使用封闭的平台来助长由全职工作到",-1)),a(n,{href:"https://en.wikipedia.org/wiki/Access_economy"},{default:e(()=>[...t[0]||(t[0]=[o("零工经济",-1)])]),_:1}),t[2]||(t[2]=o("的转变，这种方式提供极少的安全性与确定性。",-1))]),t[26]||(t[26]=r("p",null,"这项行动对于网络以及每一个使用与依赖网络的人产生了广泛的影响。仅仅二十多年前的对开放互联网的想象正在逐渐消逝，并迅速地被一块难以穿透的幕帘所取代。",-1)),r("p",null,[t[6]||(t[6]=o("一种逐渐流行的补救办法就是建立",-1)),r("ruby",null,[a(n,{href:"https://en.wikipedia.org/wiki/Platform_cooperative"},{default:e(()=>[...t[3]||(t[3]=[o("平台合作社",-1)])]),_:1}),t[4]||(t[4]=r("rt",null,"platform cooperatives",-1))]),t[7]||(t[7]=o("， 即由他们的用户所拥有的电子化平台。正如这本书",-1)),a(n,{href:"http://www.orbooks.com/catalog/ours-to-hack-and-to-own/"},{default:e(()=>[...t[5]||(t[5]=[o("《Ours to Hack and to Own》",-1)])]),_:1}),t[8]||(t[8]=o("所阐述的，平台合作社背后的观点与开源有许多相同的根源。",-1))]),t[27]||(t[27]=u('<p>学者 Trebor Scholz 和作家 Nathan Schneider 已经收集了 40 篇论文，探讨平台合作社作为普通人可使用的工具的增长及需求，以提升开放性并对闭源系统的不透明性及各种限制予以还击。</p><h3 id="何处适合开源" tabindex="-1">何处适合开源 <a class="header-anchor" href="#何处适合开源" aria-label="Permalink to “何处适合开源”">​</a></h3><p>任何平台合作社核心及接近核心的部分依赖于开源；不仅开源技术是必要的，构成开源开放性、透明性、协同合作以及共享的准则与理念同样不可或缺。</p><p>在这本书的介绍中，Trebor Scholz 指出：</p><blockquote><p>与斯诺登时代的互联网黑盒子系统相反，这些平台需要使它们的数据流透明来辨别自身。他们需要展示客户与员工的数据在哪里存储，数据出售给了谁以及数据用于何种目的。</p></blockquote><p>正是对开源如此重要的透明性，促使平台合作社如此吸引人，并在目前大量已有平台之中成为令人耳目一新的变化。</p><p>开源软件在《Ours to Hack and to Own》所分享的平台合作社的构想中必然充当着重要角色。开源软件能够为群体建立助推合作社的技术基础设施提供快速而不算昂贵的途径。</p><p>Mickey Metts 在论文中这样形容， “邂逅你的友邻技术伙伴。&quot; Metts 为一家名为 Agaric 的企业工作，这家企业使用 Drupal 为团体及小型企业建立他们不能自行完成的平台。除此以外, Metts 还鼓励任何想要建立并运营自己的企业的公司或合作社的人接受自由开源软件。为什么呢？因为它是高质量的、并不昂贵的、可定制的，并且你能够与由乐于助人而又热情的人们组成的大型社区产生联系。</p><h3 id="不总是开源的-但开源总在" tabindex="-1">不总是开源的，但开源总在 <a class="header-anchor" href="#不总是开源的-但开源总在" aria-label="Permalink to “不总是开源的，但开源总在”">​</a></h3><p>这本书里不是所有的论文都关注或提及开源的；但是，开源方式的关键元素——合作、社区、开放治理以及电子自由化——总是在其间若隐若现。</p><p>事实上正如《Ours to Hack and to Own》中许多论文所讨论的，建立一个更加开放、基于平常人的经济与社会区块，平台合作社会变得非常重要。用 Douglas Rushkoff 的话讲，那会是类似 Creative Commons 的组织“对共享知识资源的私有化”的补偿。它们也如 Barcelona 的 CTO Francesca Bria 所描述的那样，是“通过确保市民数据安全性、隐私性和权利的系统”来运营他们自己的“分布式通用数据基础架构”的城市。</p><h3 id="最后的思考" tabindex="-1">最后的思考 <a class="header-anchor" href="#最后的思考" aria-label="Permalink to “最后的思考”">​</a></h3><p>如果你在寻找改变互联网以及我们工作的方式的蓝图，《Ours to Hack and to Own》并不是你要寻找的。这本书与其说是用户指南，不如说是一种宣言。如书中所说，《Ours to Hack and to Own》让我们略微了解如果我们将开源方式准则应用于社会及更加广泛的世界我们能够做的事。</p><hr><p>作者简介:</p><p>Scott Nesbitt ——作家、编辑、雇佣兵、 <ruby>虎猫牛仔<rt>Ocelot wrangle</rt></ruby>、丈夫与父亲、博客写手、陶器收藏家。Scott 正是做这样的一些事情。他还是大量写关于开源软件文章与博客的长期开源用户。你可以在 Twitter、Github 上找到他。</p><hr>',17)),r("p",null,[t[10]||(t[10]=o("via: ",-1)),a(n,{href:"https://opensource.com/article/17/1/review-book-ours-to-hack-and-own"},{default:e(()=>[...t[9]||(t[9]=[o("https://opensource.com/article/17/1/review-book-ours-to-hack-and-own",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=o("作者：",-1)),a(n,{href:"https://opensource.com/users/scottnesbitt"},{default:e(()=>[...t[11]||(t[11]=[o("Scott Nesbitt",-1)])]),_:1}),t[15]||(t[15]=o(" 译者：",-1)),a(n,{href:"https://github.com/darsh8"},{default:e(()=>[...t[12]||(t[12]=[o("darsh8",-1)])]),_:1}),t[16]||(t[16]=o(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=o("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:e(()=>[...t[18]||(t[18]=[o("Linux中国",-1)])]),_:1}),t[21]||(t[21]=o(" 荣誉推出",-1))])])}const H=s(d,[["render",k]]);export{g as __pageData,H as default};
